quests[36934] = { id = 36934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Terror of the Tushui", description = "<Raza'kul hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all pandaren that stand defiantly against the Horde. Let their deaths serve as a warning to the rest of the Alliance: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of pandaren.\n\nConquer our enemy and be known as terror of the Tushui. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as terror of the Tushui.", objectives = "Kill 500 Pandaren Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36935] = { id = 36935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phantom Potion", description = "Every turn you take in Ashran you run into danger. But don't fret {name}, I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. \n\nI'm just missing one of the ingredients: cave mushrooms. \n\nLuckily, a variety grows right here in Ashran.", progress = "Are those the truffles?", completion = "Here she is! Careful with her, these potions have a reputation for mysteriously disappearing.", objectives = "Bring Tyra Silverblood 10 Ghost Truffles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36936] = { id = 36936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Leorajh" }
quests[36937] = { id = 36937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talador - Bladefury Treasure - Burning Blade Cache" }
quests[36940] = { id = 36940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning Orgrimmar", description = "We have slowed the Iron Horde down, but this war is far from over... I'll stay here and continue our efforts to hold back the Iron Horde.\n\nThe Warchief needs to know about what we have accomplished here today, and the threat we face in the future.\n\nIt is probably best if you report to High Overlord Saurfang yourself, {class}.", completion = "This is more trouble than I first tink. Da Iron Horde be strong, but we are da true Horde, and we be stronger.\n\nI fear this is da start of much bloodshed, before we go ta war, we be needin' a plan.", objectives = "Speak with High Overlord Saurfang.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36941] = { id = 36941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the King", description = "We have slowed the Iron Horde down, but this war is far from over... I'll stay here and continue our efforts to hold back the Iron Horde.\n\nThe King needs to know about what we have accomplished here today, and the threat we face in the future.\n\nIt is probably best if you report to King Wrynn yourself, {name}.", completion = "This is worse than I imagined.\n\nThe Iron Horde is proving to be a massive threat to our people... I don't want anymore bloodshed, but I fear we are out of options.\n\nWe need a plan before we strike.", objectives = "Speak with King Anduin Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36942] = { id = 36942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulbinder Aedraa" }
quests[36943] = { id = 36943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 030 - Gaze" }
quests[36944] = { id = 36944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besting a Boar", description = "The great boars of Gorgrond appear to serve as both a mount and an excellent source of food. Having a few of them in the garrison would not be an unwise idea.\n\nI have created for you another rope, should you wish to ride one down. Be wary of the Iron Horde presence nearby.", completion = "The boar has taken to the stables quite quickly. They appear to be nearly domesticated already. It will need some time to rest.", objectives = "Use the Boar Lasso on a Young Rocktusk and follow it until it is tamed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36945] = { id = 36945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Requisition a Riverbeast", description = "I have seen great beasts floating slowly along the rivers of Talador. The 'riverbeasts,' I believe they are called.\n\nTheir hides are solid, like rock, and yet they float along the waters easily. I would quite like to see one of these up close, if you should head that way. Tormak has created for you another rope, if you are interested.", completion = "Quite a sight, I must say. Big and powerful, yet full of so much air. It will be ready for training tomorrow.", objectives = "Use the Riverbeast Lasso on a Young Riverwallow and follow it until it is tamed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36946] = { id = 36946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entangling an Elekk", description = "The plains of Nagrand are the most lush and fertile that I have ever seen. Should you ever see them, you will come upon the mightiest beasts that this place has to offer.\n\nAmong them, the great elekk. A magnificent beast with horns that can grow larger than you or I.\n\nHere is another rope, should you wish to tangle with such a beast.", completion = "A powerful creature, it nearly took down the wooden posts of the stable. We will begin training it as soon as it wakes.", objectives = "Use the Elekk Lasso on a Young Meadowstomper and follow it until it is tamed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36947] = { id = 36947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Strength", objectives = "I have been training hard since I joined your forces, commander.\n\nLet me prove my new strength to you so that I am worthy to fight by your side. All will tremble at the sight of us on the battlefield!You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36948] = { id = 36948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auctioning for Parts", progress = "<The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. \n\nIf you found all of these items, you're confident you could restore it>", completion = "You can hear the power building inside the unit..." }
quests[36950] = { id = 36950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrangling a Wolf", description = "The wolves of this land have jaws of steel. It is no wonder that the orcs have taken them as their own.\n\nYet, deep in Nagrand, there are young wolves, ripe for taming. They will present a great challenge to you, as they are more fast and agile than any beast in this land.\n\nHere is your final rope, may luck be with you.", completion = "Quite the catch, commander. It will need to rest for some time, but will surely be hungry for combat soon.", objectives = "Use the Wolf Lasso on a Young Snarler and follow it until it is tamed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36951] = { id = 36951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arakkoa Exodus", description = "I assume you're familiar with the arakkoa, commander? Great, flying birdfolk. Extremely territorial.\n\nSome, however, have withered wings - a disease, maybe. They seem to be outcast from arakkoa society. You find them now and then, squatting in forgotten ruins or peddling trinkets on the roadside.\n\nIt seems the Iron Horde has incited the arakkoa by moving into their lands, and the outcasts are fleeing in droves.\n\nWe should make contact with these outcasts - they could have valuable information.", completion = "<The arakkoa merchant looks you up and down.>\n\nWell-equipped, aren't we? Azik is betting you are someone of importance to your people.\n\nCome closer, friend. Speak with me for just a moment.", objectives = "Speak with Azik in Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36952] = { id = 36952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Fight to Nagrand", description = "**Eyes Only -- Commander {name}**\n\nDurotan recommended dat we be gettin' a foothold in Nagrand, so I taken the liberty of dispatchin' some of da boys.\n\nThrall's already reportin' the new outpost be nearly complete. He been askin' me to let ya know they be ready for ya.\n\nA windrider be waitin' to catch ya up with the latest caravan shipment whenever you be ready, <sir/ma'am>.\n\n-- Rokhan", completion = "They came at us... from... nowhere.\n\n<The stoneguard nearly passes out.>", objectives = "Speak with Stone Guard Brox at the caravan in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36953] = { id = 36953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Matter of Strategy", description = "**Eyes Only -- Commander {name}**\n\nThe Iron Horde have proved themselves worthy foes.\n\nThey managed to get their fleet moving to Talador from Gorgrond without my spies seeing a thing. Talador be a crossroads for the whole continent. We can't let them have it.\n\nDon't worry boss, we got a plan. Foreman Grobash be setting up an outpost for our forces as we speak. They be ready for you when you arrive, commander.\n\n--Rokhan", completion = "Your will be done. I require your advisement, commander.", objectives = "Speak to Bron Skyhorn to secure a flight to Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36955] = { id = 36955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Hunter - Hunted", description = "Our enemies surround us, and with each passing day their numbers grow. It is time to make a decisive strike against their armies, champion.\n\nAround me stand effigies of our most hated adversaries. You will be their downfall, {name}. You will become nemesis and they will run in fear at the sight of you.\n\nNow select the target of your rage and burn in effigy that race which you mean to eradicate. Speak to me when you have made your selection.", completion = "A last warning: once you have accepted this choice you cannot reverse it or make a new choice until you complete your mission.\n\nIf your choice is certain, your aim will be true.\n\nStrike fear in the hearts and minds of the enemy! Glory to the Alliance! For Draenor!", objectives = "Burn a Nemesis Effigy at the Gladiator's Sanctum then speak to Kuros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36956] = { id = 36956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis Flag, Human" }
quests[36957] = { id = 36957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a blood elf in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill a Blood Elf Player in Player versus Player combat while in Draenor and retrieve their Blood Elf Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36958] = { id = 36958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Slayer of Sin'dorei", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all blood elves that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of blood elf.\n\nConquer our enemy and be known as slayer of Sin'dorei. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as slayer of Sin'dorei.", objectives = "Kill 500 Blood Elf Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36959] = { id = 36959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the mostly-dead heart of a Forsaken in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill a Forsaken Player in Player versus Player combat while in Draenor and retrieve their Forsaken Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36960] = { id = 36960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Death Stalker", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all Forsaken that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the black blood of Forsaken.\n\nConquer our enemy and be known as death stalker. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as death stalker.", objectives = "Kill 500 Forsaken Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36961] = { id = 36961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a tauren in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill a Tauren Player in Player versus Player combat while in Draenor and retrieve their Tauren Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36962] = { id = 36962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: The Butcher", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all tauren that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of tauren.\n\nConquer our enemy and be known as the butcher. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as the butcher.", objectives = "Kill 500 Tauren Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36963] = { id = 36963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of an orc in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill an Orc Player in Player versus Player combat while in Draenor and retrieve their Orc Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36964] = { id = 36964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Orcslayer", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all orcs that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of orc.\n\nConquer our enemy and be known as orcslayer. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as orcslayer.", objectives = "Kill 500 Orc Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36965] = { id = 36965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a troll in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill a Troll Player in Player versus Player combat while in Draenor and retrieve their Troll Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36966] = { id = 36966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Troll Hunter", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all trolls that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of troll.\n\nConquer our enemy and be known as troll hunter. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as troll hunter.", objectives = "Kill 500 Troll Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36967] = { id = 36967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a pandaren in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill a Pandaren Player in Player versus Player combat while in Draenor and retrieve their Pandaren Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36968] = { id = 36968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Huojin's Fall", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all pandaren that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of pandaren.\n\nConquer our enemy and be known as Huojin's fall. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as Huojin's fall.", objectives = "Kill 500 Pandaren Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36969] = { id = 36969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a goblin in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults.", objectives = "Kill a Goblin Player in Player versus Player combat while in Draenor and retrieve their Goblin Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36970] = { id = 36970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nemesis: Killer of Kezan", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all goblins that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of goblin.\n\nConquer our enemy and be known as the killer of Kezan. Fail and be nothing.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as killer of Kezan.", objectives = "Kill 500 Goblin Players in Player versus Player combat across Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36971] = { id = 36971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Great-Tusk", description = "The first step in training your mount for war will be getting it used to the sights and sounds of combat. If it's not trained properly, it might get spooked and run.\n\nTake this little talbuk out to the plains of Shadowmoon Valley and take on the biggest beast you can find, together. That should raise its confidence!", progress = "Did you manage to bring down Great-Tusk?", completion = "That should do it a world of good. We'll let 'er rest for tonight, and take on some bigger targets tomorrow.", objectives = "Defeat Great-Tusk while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36972] = { id = 36972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Rakkiri", description = "Now that your talbuk has got a taste for combat, let's take it out into an environment it may not be familiar with.\n\nThe icy bluffs of Frostfire Ridge should be a good test. Find yourself a big, mean beast out there and take it down with your talbuk.", completion = "Oi! That talbuk's performin' admirably. Let's let 'er rest.", objectives = "Defeat Rakkiri while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36973] = { id = 36973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Riplash", description = "Now plenty of mounts have been known to run away at the sight of a fierce predator. Way out in the desolate cliffs of Gorgrond, they've got some of the fiercest.\n\nLet's put your talbuk to the test. See if the two of you can't take down the mighty raptor known as Riplash.", completion = "Those were some mighty big claws to tangle with. Your talbuk will need a nap after that one.", objectives = "Defeat Riplash while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36974] = { id = 36974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Gezz'ran", description = "There's plenty more beasts out in the wild that can make a snack of your favorite mount. One of the most cunning on Draenor is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your talbuk can't overcome this natural defense mechanism. You'll find some mean stalkers out in Talador.", completion = "Ye did it! I'm sure your talbuk's enjoyin' this sort of one-on-one attention. We'll let it rest up a bit.", objectives = "Defeat Gezz'ran while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36975] = { id = 36975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Bulbapore", description = "Way down south in the Spires of Arak, the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place.\n\nTaking on a strange creature, like the fungal giant Bulbapore, gives us a great chance to expose your talbuk to predators it's unfamiliar with.", completion = "I'll bet that was quite a fight! Great job, let's let it rest for tonight.", objectives = "Defeat Bulbapore while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36976] = { id = 36976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your talbuk reacts to that.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training.", objectives = "Defeat the Gorian Beast-Lasher while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36977] = { id = 36977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of 'em.\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", completion = "From now on, I'm sure your mount will always remember to keep one eye on the skies. Great job!", objectives = "Defeat the Darkwing Roc while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36978] = { id = 36978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your talbuk. See if you can't keep it focused and take down that moth.", completion = "Glad to see you two make it back. It'll need a bit of time to brush that dust off.", objectives = "Defeat the Moth of Wrath while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36979] = { id = 36979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your talbuk and face off against Thundercall, and we'll see if it gets spooked.", completion = "Well, it's a bit wet, but seems to be in good spirits. I'll get 'er dried off and into bed.", objectives = "Defeat Thundercall while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36980] = { id = 36980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Ironbore", description = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out!\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your talbuk on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore.", completion = "The sand worm's bit the dust? Well done, I'll get this beast bedded down for the night.", objectives = "Defeat Ironbore while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36981] = { id = 36981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your talbuk and bring him down. In the name of the poor wee beasts!", completion = "Hunted the hunter, eh? Your beast doesn't seem any worse for wear, either! I'll brush it down.", objectives = "Defeat Karak the Great Hunter while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36982] = { id = 36982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.", completion = "Your talbuk has grown from a wee silverpelt into a fine specimen of war beast, and it's all due to your diligence.\n\nI'm happy to hand over the reins of this fully-trained mount to you, commander. Ride it with pride!", objectives = "Defeat Maimclaw while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36983] = { id = 36983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Great-Tusk", description = "The first step in training your mount for war will be getting it used to the sights and sounds of combat. If it's not trained properly, it might get spooked and run.\n\nTake this little clefthoof out to the plains of Shadowmoon Valley and take on the biggest beast you can find, together. That should raise its confidence!", completion = "That should do it a world of good. We'll let 'er rest for tonight, and take on some bigger targets tomorrow.", objectives = "Defeat Great-Tusk while riding your Clefthoof -In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36984] = { id = 36984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Rakkiri", description = "Now that the clefthoof has a taste for combat, let's take it out into a harsher environment.\n\nTake your clefthoof out to the icy hills of Frostfire Ridge, and take on the great predator Rakkiri. We'll really put 'er toughness to the test.", completion = "Oi! That clefthoof's performin' admirably. Let's let 'er rest.", objectives = "Defeat Rakkiri while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36985] = { id = 36985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Riplash", description = "Now plenty of mounts have been known to run away at the sight of a fierce predator. Way out in the desolate cliffs of Gorgrond, they've got some of the fiercest.\n\nLet's put your talbuk to the test. See if the two of you can't take down the mighty raptor known as Riplash.", completion = "Those were some mighty big claws to tangle with. Your clefthoof will need a nap after that one.", objectives = "Defeat Riplash while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
