quests[37003] = { id = 37003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your boar and bring him down. In the name of the poor wee beasts!", completion = "Hunted the hunter, eh? Your beast doesn't seem any worse for wear, either! I'll brush it down.", objectives = "Defeat Karak the Great Hunter while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37004] = { id = 37004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your boar, mount up, and bring it down. If the two of you survive, your boar will truly be ready.", completion = "Your rocktusk is now ready to see combat, commander. Here's the reins, you'll need 'em ridin' this bucket of muscle!\n\nGreat job with the training!", objectives = "Defeat Maimclaw while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37005] = { id = 37005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Gezz'ran", description = "This beast's spent quite a few years out in the wilds of Talador, I'd say we start the training there. It's fairly docile, as well. I don't think it will take quite as long to train as the others.\n\nAs ye probably know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", completion = "Ye did it! I'm sure your riverbeast's enjoyin' this sort of one-on-one attention. We'll let it rest up a bit.", objectives = "Defeat Gezz'ran while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37006] = { id = 37006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Bulbapore", description = "Way down south in the Spires of Arak, the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place.\n\nTaking on a strange creature, like the fungal giant Bulbapore, gives us a great chance to expose your riverbeast to predators it's unfamiliar with.", completion = "I'll bet that was quite a fight! Great job, let's let it rest for tonight.", objectives = "Defeat Bulbapore while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37007] = { id = 37007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your riverbeast reacts to that.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training.", objectives = "Defeat the Gorian Beast-Lasher while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37008] = { id = 37008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.'\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", completion = "From now on, I'm sure your mount will always remember to keep one eye on the skies. Great job!", objectives = "Defeat the Darkwing Roc while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
