quests[37012] = { id = 37012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your riverbeast and bring him down. In the name of the poor wee beasts!", completion = "Hunted the hunter, eh? Your beast doesn't seem any worse for wear, either! I'll brush it down.", objectives = "Defeat Karak the Great Hunter while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37013] = { id = 37013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your riverbeast, mount up, and bring it down. If the two of you survive, your riverbeast will truly be ready.", completion = "You know, I didn't really believe you when you decided to start training this thing. But here it is, a trained riverwallow.\n\nI guess if a beast needs training, you're the one to do it! Great work, commander!", objectives = "Defeat Maimclaw while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37014] = { id = 37014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auctioning for Parts", progress = "<The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. \n\nIf you found all of these items, you're confident you could restore it>", completion = "You can hear the power building inside the unit." }
quests[37015] = { id = 37015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Cruel Ogres", description = "This beast is surely at home in Nagrand, and I bet ye after all of the years of domestication by Draenei, it's going to be a snap to train.\n\nLet's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher, the one that smells of blood and fear, go on and see how your elekk  reacts to that.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training.", objectives = "Defeat the Gorian Beast-Lasher while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37016] = { id = 37016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.'\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", completion = "From now on, I'm sure your mount will always remember to keep one eye on the skies. Great job!", objectives = "Defeat the Darkwing Roc while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37017] = { id = 37017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your elekk. See if you can't keep it focused and take down that moth.", completion = "Glad to see you two make it back. It'll need a bit of time to brush that dust off.", objectives = "Defeat the Moth of Wrath while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37018] = { id = 37018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your elekk and face off against Thundercall, and we'll see if it gets spooked.", completion = "Well, it's a bit wet, but seems to be in good spirits. I'll get 'er dried off and into bed.", objectives = "Defeat Thundercall while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37019] = { id = 37019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Ironbore", description = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out!\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your elekk on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore.", completion = "The sand worm's bit the dust? Well done, I'll get this beast bedded down for the night.", objectives = "Defeat Ironbore while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37020] = { id = 37020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your elekk and bring him down. In the name of the poor wee beasts!", completion = "Hunted the hunter, eh? Your beast doesn't seem any worse for wear, either! I'll brush it down.", objectives = "Defeat Karak the Great Hunter while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37021] = { id = 37021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", completion = "A fine beast, to be sure, commander. It'll stand up in even the toughest battles.\n\nI'll admit, I'm a bit jealous of ye'! Here's the reins! I'll be sure to take good care of it when ye bring it back.", objectives = "Defeat Maimclaw while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37022] = { id = 37022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Cruel Ogres", description = "The wolves of Draenor are some of the most savage beasts around, but they've also gotten used to the sights and smells of the orcs and ogres that live here. It shouldn't take us much time at all to train this little ball of fur and death.\n\nLet's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher, the one that smells of blood and fear, go on and see how your wolf reacts to that.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training.", objectives = "Defeat the Gorian Beast-Lasher while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37023] = { id = 37023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.'\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", completion = "From now on, I'm sure your mount will always remember to keep one eye on the skies. Great job!", objectives = "Defeat the Darkwing Roc while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37024] = { id = 37024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your wolf. See if you can't keep it focused and take down that moth.", completion = "Glad to see you two make it back. It'll need a bit of time to brush that dust off.", objectives = "Defeat the Moth of Wrath while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
