quests[37026] = { id = 37026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Ironbore", description = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out!\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your wolf on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore.", completion = "The sand worm's bit the dust? Well done, I'll get this beast bedded down for the night.", objectives = "Defeat Ironbore while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37027] = { id = 37027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your wolf and bring him down. In the name of the poor wee beasts!", completion = "Hunted the hunter, eh? Your beast doesn't seem any worse for wear, either! I'll brush it down.", objectives = "Defeat Karak the Great Hunter while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37028] = { id = 37028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.", completion = "I can't believe you've managed to train your wolf already! It feels like it was just yesterday that the little ball of fur and death came into my stables.\n\nI'll hand it to ye, that's a fierce little mount ye got there. Here's the reins, enjoy!", objectives = "Defeat Maimclaw while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37029] = { id = 37029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of the Black Hand", description = "<Goraluk sighs with... relief? ...or perhaps regret?>\n\nOnce I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers.\n\nThe Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", progress = "I will require essences from each of the Foundry's guardians if this is to work.", completion = "You have done it!\n\n<Goraluk takes the items from your hands, and turns his back for a few moments>\n\nNow, I will touch this Sigil to your hand, and the entrance to the Crucible will open at your touch. Good luck.", objectives = "Collect 4 Embers of the Mountain, 4 Hearts of Stone, and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Normal difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37030] = { id = 37030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of the Black Hand (Heroic)", description = "<Goraluk sighs with... relief? ...or perhaps regret?>\n\nOnce I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers.\n\nThe Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", progress = "I will require essences from each of the Foundry's guardians if this is to work.", completion = "You have done it!\n\n<Goraluk takes the items from your hands, and turns his back for a few moments>\n\nNow, I will touch this Sigil to your hand, and the entrance to the Crucible will open at your touch. Good luck.", objectives = "Collect 4 Embers of the Mountain, 4 Hearts of Stone, and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37031] = { id = 37031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of the Black Hand (Mythic)", description = "<Goraluk sighs with... relief? ...or perhaps regret?>\n\nOnce I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers.\n\nThe Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", progress = "I will require essences from each of the Foundry's guardians if this is to work.", completion = "You have done it!\n\n<Goraluk takes the items from your hands, and turns his back for a few moments>\n\nNow, I will touch this Sigil to your hand, and the entrance to the Crucible will open at your touch. Good luck.", objectives = "Collect 4 Embers of the Mountain, 4 Hearts of Stone, and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37032] = { id = 37032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Riplash", description = "This boar is at home in the rocky plains of Gorgrond, so it will be easier to train. As with other beasts, we will begin the training in the place it calls home.\n\nTest your boar against the great predator Riplash, a raptor known to hunt boars.", completion = "A mighty kill. Your beast will need to rest now.", objectives = "Defeat Riplash while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37033] = { id = 37033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Gezz'ran", description = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning on is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water.", objectives = "Defeat Gezz'ran while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37034] = { id = 37034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", completion = "You have returned victorious. I will bed your mount down for the night.", objectives = "Defeat Bulbapore while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37035] = { id = 37035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your beast reacts to that.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well.", objectives = "Defeat the Gorian Beast-Lasher while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37036] = { id = 37036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", completion = "From now on, your mount will always remember to keep one eye on the skies.", objectives = "Defeat the Darkwing Roc while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37037] = { id = 37037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your boar. See if you can keep it focused and defeat the moth.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount.", objectives = "Defeat the Moth of Wrath while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37038] = { id = 37038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest.", objectives = "Defeat Thundercall while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37039] = { id = 37039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night.", objectives = "Defeat Ironbore while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37040] = { id = 37040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight.", objectives = "Defeat Karak the Great Hunter while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37041] = { id = 37041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boar Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your boar, mount up, and bring it down. If the two of you survive, your boar will truly be ready.", completion = "The garn is defeated, and your boar is now ready to see combat. Here are the reins, may you never part company.", objectives = "Defeat Maimclaw while riding your Boar-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37043] = { id = 37043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scraps of Iron", description = "At the armory, we can take scraps of Iron Horde armor that you collect and turn them into new gear. It's not the strongest stuff in the world, but it looks good.\n\nGet some Iron Horde scraps and come back my way. I'll set you up with a nice tabard for your troubles.", progress = "Got those scraps?", completion = "Those scraps will do.", objectives = "Collect 5 Iron Horde Scraps from Iron Horde on Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37044] = { id = 37044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unconventional Inventions", description = "We've got a lot goin' on here at the workshop. We're buildin' new inventions all the time, and you can find 'em behind me on the workbench.\n\nGo ahead and grab today's glorious invention. Use it at your own risk.", progress = "A goblin workshop can get dangerous. Watch out for exploding explosives!", completion = "Pretty cool invention you have there.", objectives = "Acquire an invention from the workbench at your Goblin Workshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37045] = { id = 37045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Situation", description = "Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful.\n\nI have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?", progress = "Have you burned through that bag of salvage yet?", completion = "That's all? Well. don't feel too bad. Some days we find nothing and the next we hit the jackpot!\n\nHere, I have a fresh supply of items from our latest outing. Check them out.\n\nGood luck!", objectives = "Use the Small Sack of Salavaged Goods near the incinerator at your Salvage Yard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37046] = { id = 37046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headhunter's Harvest", description = "Hey der mon, I be ya new headhunter. \nThe tavern be a perfect place for adventurers to rest after a long journey. It also be a great place to talk them into joining our cause.\n\nI be havin' a few recruits for ya to look at, if ya find one we can hire then I'll give ya a little somethin' as a finder fee for ya time.", progress = "Ya find a recruit ya like?", completion = "I'm glad ya be findin' a good hire!\n\nMake sure to check back every week and I'll bring ya me latest recruits.", objectives = "Recruit a follower from Akanja in the Frostwall Tavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37047] = { id = 37047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light's Gift", objectives = "The Light has blessed me with newfound power, commander.\n\nNow none can stand against our conviction!You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37048] = { id = 37048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Great-Tusk", description = "The next  step in training your mount for war will be getting it used to the sights and sounds of combat. If it is not trained properly, it might become afraid at a very inopportune time.\n\nThough small, take your clefthoof to the plains of Shadowmoon Valley and find the greatest beast you can. It will grow quickly against such a foe.", completion = "Your clefthoof appears worn, but happy. You have done well, let it rest for a while.", objectives = "Defeat Great-Tusk while riding your Clefthoof -In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37049] = { id = 37049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Rakkiri", description = "Your clefthoof is most at home here in Frostfire Ridge, and that is where we will begin the training.\n\nOut on the icy plains, you will find a hunter of blood and death. The winged terror Rakkiri is feared by beasts across this region, and will prove a good first test for your future mount.", completion = "The clefthoof is in good shape, you are a fine trainer for the beast. It will require some rest.", objectives = "Defeat Rakkiri while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37050] = { id = 37050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Riplash", description = "Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge.\n\nTake your beast to the nest of the great Riplash, and see if you cannot emerge victorious.", completion = "A mighty kill. Your beast will need to rest now.", objectives = "Defeat Riplash while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37051] = { id = 37051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Gezz'ran", description = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning on is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water.", objectives = "Defeat Gezz'ran while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37052] = { id = 37052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", completion = "You have returned victorious. I will bed your mount down for the night.", objectives = "Defeat Bulbapore while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37053] = { id = 37053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your beast reacts to that.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well.", objectives = "Defeat the Gorian Beast-Lasher while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37054] = { id = 37054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", completion = "From now on, your mount will always remember to keep one eye on the skies.", objectives = "Defeat the Darkwing Roc while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37055] = { id = 37055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your clefthoof. See if you can keep it focused and defeat the moth.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount.", objectives = "Defeat the Moth of Wrath while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37056] = { id = 37056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest.", objectives = "Defeat Thundercall while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37057] = { id = 37057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores and test it against the elder worm Ironbore.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night.", objectives = "Defeat Ironbore while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37058] = { id = 37058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight.", objectives = "Defeat Karak the Great Hunter while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37059] = { id = 37059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clefthoof Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your clefthoof, mount up, and bring it down. If the two of you survive, your clefthoof will truly be ready.", completion = "The clefthoof is now fully-trained and prepared to be your mount. Take care of the beast, I hope to see the two of you again shortly.", objectives = "Defeat Maimclaw while riding your Clefthoof-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37060] = { id = 37060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Transition", description = "<Sir/Ma'am>, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for.\n\nUnfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters.\n\nIf you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", progress = "Hello commander, what can I do for you?", completion = "Thank you, according to the ledger that appears to be everything we're missing.\nThose peons are going to be cleaning the latrines tonight for this!", objectives = "Gather 5 Crate of Surplus Materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37062] = { id = 37062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tricks of the Trade", description = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean.\n\nSometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time.\n\nLuckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", progress = "Trading isn't always the most exciting enterprise. But I do enjoy it.", completion = "You have learned one of my tricks of the trade, {name}.", objectives = "Find and rouse the missing Trader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37063] = { id = 37063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Cruel Ogres", description = "This beast is surely at home in Nagrand, and after the years of domestication by Draenei it will be quite easy to train.\n\nWe shall face it against the ogres of the region that you are familiar with. The Gorian Beast-Lasher, the one that smells of blood and fear, see how this elekk reacts to him.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well.", objectives = "Defeat the Gorian Beast-Lasher while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37064] = { id = 37064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", completion = "From now on, your mount will always remember to keep one eye on the skies.", objectives = "Defeat the Darkwing Roc while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37065] = { id = 37065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your elekk. See if you can keep it focused and defeat the moth.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount.", objectives = "Defeat the Moth of Wrath while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37066] = { id = 37066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest.", objectives = "Defeat Thundercall while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37067] = { id = 37067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night.", objectives = "Defeat Ironbore while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37068] = { id = 37068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight.", objectives = "Defeat Karak the Great Hunter while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37069] = { id = 37069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elekk Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", completion = "A fine beast, sure to be your companion in many battles to come. Here are the reins, be strong but fair in your care of this great beast.", objectives = "Defeat Maimclaw while riding your Meadowstomper-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37070] = { id = 37070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Nether", objectives = "Fighting alongside you has strengthened my connection to the nether like never before, commander.\n\nI will use my new power to rain death down upon your enemies. They will learn to fear you.You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37071] = { id = 37071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Gezz'ran", description = "This bulbous beast has spent a number of years in the wilds of Talador. We will begin the training there. It is already docile, as well, so I do not think it will take as long to train as the others.\n\nAs you know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water.", objectives = "Defeat Gezz'ran while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37072] = { id = 37072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", completion = "You have returned victorious. I will bed your mount down for the night.", objectives = "Defeat Bulbapore while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37073] = { id = 37073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your beast reacts to that.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well.", objectives = "Defeat the Gorian Beast-Lasher while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37074] = { id = 37074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", completion = "From now on, your mount will always remember to keep one eye on the skies.", objectives = "Defeat the Darkwing Roc while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37075] = { id = 37075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your riverbeast. See if you can keep it focused and defeat the moth.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount.", objectives = "Defeat the Moth of Wrath while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37076] = { id = 37076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest.", objectives = "Defeat Thundercall while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37077] = { id = 37077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night.", objectives = "Defeat Ironbore while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37078] = { id = 37078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight.", objectives = "Defeat Karak the Great Hunter while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37079] = { id = 37079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riverbeast Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your riverbeast, mount up, and bring it down. If the two of you survive, your riverbeast will truly be ready.", completion = "I had never seen such a beast before coming here, but you have trained it. No small feat, to be certain. Take the reins, you have earned them.", objectives = "Defeat Maimclaw while riding your Riverbeast-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37080] = { id = 37080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorious Slaughter", objectives = "The blood o' our fallen foes has not yet sated my thirst, commander.\n\nI have a trick up me sleeve that ought ta help change that.You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37081] = { id = 37081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Rage", objectives = "We have shown far too much mercy to your enemies, commander.\n\nIf you would allow me, I have a spell I've been perfecting that will show them what happens when you stand in our way.You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37082] = { id = 37082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Gladiator", description = "Your merciless rampage has not gone unnoticed, gladiator. So many of your enemies have fallen before your might. It is because of your unrelenting savagery that Imperator Mar'gok himself has requested your presence at the grand Highmaul Coliseum. It is at Highmaul that a battle of epic proportions awaits.\n\nShould you heed the call of the gladiator, present this sigil to my brother, Kharg. He is the arena master residing outside of the Coliseum in Nagrand.", completion = "A bold decision, gladiator. For most, death is the only thing they find at the Coliseum. Surviving here is more than a test of skill, it is a test of wills. Do you have the fortitude to become a champion?", objectives = "Take the Sigil of Highmaul to Kharg outside the Highmaul Coliseum in Nagrand.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37083] = { id = 37083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight, Kill, Salute!", description = "The greatest gladiators on Draenor have fought for glory and honor inside the Coliseum. Will you become a legend like Kargath Bladefist or will you be nothing more than bone dust beneath the boots of a more savage gladiator? There is only one way to find out.\n\nYou must enter the competition and fight! The price of victory is 100 lives!\n\nI will admit you without cost once per day, but if you fail and wish to fight again you must pay the price of admission in blood and bone!", completion = "Remarkable! You have proven yourself a true gladiator. And to a true gladiator goes more than honor and glory!", objectives = "Kill 100 Gladiators at the Coliseum in Highmaul.\n\nYou may access the Coliseum by talking to Kharg at Highmaul or Boneslag at your Gladiator's Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37084] = { id = 37084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadows Call", objectives = "The shadows... they have taught me how to slip into the minds of our enemies.\n\nYes... turn them against their own. Our victory will be swift. Rawk!You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37085] = { id = 37085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury of the Clan", objectives = "Our clan strong. Strongest.\n\nI feed our lust, make us stronger. We win!You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37086] = { id = 37086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvaging the Situation", description = "Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful.\n\nI have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?", progress = "Have you burned through that bag of salvage yet?", completion = "That's all? Well. don't feel too bad. Some days we find nothing and the next we hit the jackpot!\n\nHere, I have a fresh supply of items from our latest outing. Check them out.\n\nGood luck!", objectives = "Use the Small Sack of Salavaged Goods near the incinerator at your Salvage Yard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37087] = { id = 37087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Transition", description = "<Sir/Ma'am>, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for.\n\nUnfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters.\n\nIf you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", progress = "Hello commander, what can I do for you?", completion = "According to the ledger this appears to be everything we're missing. Those porters will be cleaning the latrines tonight for this!", objectives = "Gather 5 Crate of Surplus Materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37088] = { id = 37088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tricks of the Trade", description = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean.\n\nSometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time.\n\nLuckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", completion = "You have learned one of my tricks of the trade, {name}.", objectives = "Find and rouse the missing Trader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37091] = { id = 37091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unconventional Inventions", description = "The workshop is bustling with the whir of minds and motors. We're coming up with new inventions all the time.\n\nTry out today's glorious invention on the workbench behind me.", completion = "Nice invention!", objectives = "Acquire an invention from the workbench at the Gnomish Gearworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37092] = { id = 37092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scraps of Iron", description = "At the Dwarven Bunker, we can take scraps of Iron Horde armor that you collect and turn them into new gear. It's not the strongest stuff in the world, but it looks good.\n\nGet some Iron Horde scraps and come back my way. I'll set you up with a nice tabard for your troubles.", progress = "Got those scraps?", completion = "Those scraps will do.", objectives = "Collect 5 Iron Horde Scraps from Iron Horde on Draenor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37093] = { id = 37093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Great-Tusk", description = "The talbuk is ready for more training, and for this, we will return to its home in Shadowmoon Valley.\n\nOne of the great beasts of this land, Great-Tusk, has taken the valley for his own. Pit your beast against him in combat, and if you should survive, it will have greater confidence in its own abilities.", completion = "That was a fine battle to test your talbuk against. It will need to rest before we can continue the training.", objectives = "Defeat Great-Tusk while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37094] = { id = 37094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Rakkiri", description = "We shall start training the talbuk here, on the icy plains of Frostfire Ridge. We must train it rigorously, or else it may become afraid at the sight of combat, and run.\n\nFind the great blood-sucker, Rakkiri, out on the frozen plains, and bring him down astride your talbuk. That will give it a taste for combat.", completion = "Your talbuk is growing quickly, let us let it rest.", objectives = "Defeat Rakkiri while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37095] = { id = 37095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Riplash", description = "Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge.\n\nTake your beast to the nest of the great Riplash, and see if you cannot emerge victorious.", completion = "A mighty kill. Your beast will need to rest now.", objectives = "Defeat Riplash while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37096] = { id = 37096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Gezz'ran", description = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water.", objectives = "Defeat Gezz'ran while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37097] = { id = 37097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", completion = "You have returned victorious. I will bed your mount down for the night.", objectives = "Defeat Bulbapore while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37098] = { id = 37098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your beast reacts to that.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well.", objectives = "Defeat the Gorian Beast-Lasher while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37099] = { id = 37099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", completion = "From now on, your mount will always remember to keep one eye on the skies.", objectives = "Defeat the Darkwing Roc while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37100] = { id = 37100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your talbuk. See if you can keep it focused and defeat the moth.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount.", objectives = "Defeat the Moth of Wrath while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37101] = { id = 37101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest.", objectives = "Defeat Thundercall while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37102] = { id = 37102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night.", objectives = "Defeat Ironbore while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37103] = { id = 37103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight.", objectives = "Defeat Karak the Great Hunter while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37104] = { id = 37104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talbuk Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.", completion = "A powerful and swift companion, and now unafraid of the creatures you may run into. You have done well in your training of the beast, and I am pleased to present you with the reins.", objectives = "Defeat Maimclaw while riding your Talbuk-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37105] = { id = 37105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Cruel Ogres", description = "The wolves of this land are the most savage beasts I have seen, and surely do not fear orc nor ogre.\n\nBring him to bear against once of the ogres that you are familiar with. The Gorian Beast-Lasher, the one that smells of blood and fear, see how the wolf reacts to him.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well.", objectives = "Defeat the Gorian Beast-Lasher while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37106] = { id = 37106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", completion = "From now on, your mount will always remember to keep one eye on the skies.", objectives = "Defeat the Darkwing Roc while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37107] = { id = 37107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your wolf. See if you can keep it focused and defeat the moth.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount.", objectives = "Defeat the Moth of Wrath while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37108] = { id = 37108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest.", objectives = "Defeat Thundercall while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37109] = { id = 37109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night.", objectives = "Defeat Ironbore while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37110] = { id = 37110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight.", objectives = "Defeat Karak the Great Hunter while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37111] = { id = 37111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolf Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.", completion = "A savage beast, yet you have tamed it. I should learn to never underestimate you. It awaits your command patiently, almost like it knows you wait for it. Here are the reins, may your companion be ever at your side.", objectives = "Defeat Maimclaw while riding your Snarler-In-Training.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37112] = { id = 37112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rest and Relaxation", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", completion = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.\n\nWould you like to try a sampling of some of our fine food and drink?", objectives = "Speak with Innkeeper Farley at the Lion's Pride Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37113] = { id = 37113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thisalee Crow", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37114] = { id = 37114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choluna", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37119] = { id = 37119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headhunter's Harvest", description = "The inn provides a perfect place for adventurers to take a rest between their travels. It's also a great place to talk them into joining our cause over a few rounds of drinks.\n\nGo through my selection and let's see if we can obtain a new recruit. I'll give you a little something as a finder's fee for your efforts.", progress = "Find a recruit that you like?", completion = "Ahh, I'm glad you were able to find a good hire!\n\nI'll get back to looking for more candidates for you. Check back in every week to see my latest selections.", objectives = "Recruit a follower from Lysa Serion in the Lunarfall Inn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37120] = { id = 37120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37121] = { id = 37121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Claw", description = "Behind me, as ye can probably see, is a giant black claw. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", completion = "Like I said, the claw has a strange effect on the mounts we've got here. If ye have it with ye when training a mount-in-training, your mount will be MUCH more vulnerable.\n\nShould ye find the training not rough enough, ye might want to challenge yourself.\n\nI'd have a pretty hefty prize for anyone that could manage that!", objectives = "Ask Fanny Firebeard about the Black Claw of Sethe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37122] = { id = 37122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teeth of a Predator", description = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything!", completion = "I've not seen the beasts go so wild in all of my years, as the day we brought this thing back to the stables.\n\nShould ye find the training still not hard enough, take it along with ye. Your mounts-in-training will be even MORE vulnerable.\n\nBe careful! I'd give a prize to anyone that could best every beast with such an artifact, but I don't want to see you wind up dead!", objectives = "Ask Fanny Firebeard about the Garn-Tooth Necklace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37123] = { id = 37123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Claw", description = "You've probably seen this enormous, black claw in our pile of supplies. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", progress = "Yes?", completion = "This claw has a strange effect on the mounts we have. If you have it with you when training a mount-in-training, your mount will be MUCH more vulnerable.\n\nShould you find the training not rough enough, you might want to challenge yourself further by carrying it with you.\n\nI think besting the beasts of Draenor with it would certainly be worthy of a reward.", objectives = "Ask Sage Paluna about the Black Claw of Sethe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37124] = { id = 37124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teeth of a Predator", description = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything.", completion = "I have not seen the beasts go so mad in all of my years as a sage, as the day we brought this necklace  back to the stables.\n\nShould you find the training still not hard enough, take it along with you. Your mounts-in-training will be even MORE vulnerable.\n\nBe careful! I would gladly reward anyone that could best every beast with such an artifact, but I do not want to see you wind up dead!", objectives = "Ask Sage Paluna about the Garn-Tooth Necklace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37125] = { id = 37125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Find", progress = "Every once in a while an archaeologist experiences a rare find... an artifact that time has delicately preserved through the ages, as if it had simply fallen out of a time machine.\n\nEven thinking about the thrill of such a find makes me get all emotional... relics like that are worth a freakin' fortune!", completion = "Nice find! This relic is going to be a welcome addition to someone's private collection!" }
quests[37126] = { id = 37126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ogre Without His Sword...", description = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\"\n\nI want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse.\n\nIt would mean a great deal to me. An ogre without his sword isn't an ogre at all.", progress = "I want my sword more than I can tell you, commander.", completion = "Yes... this is it.\n\nCommander, I will cleave your foes like never before now that I have my sword.", objectives = "Retrieve Tormmok's Favorite Sword from Vizier Dar'gud at Broken Precipice in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37127] = { id = 37127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Light of Exodus", description = "My grandfather always told me stories of a powerful crystal made of the Light that would grant power to those who intended to use it for good. He called it the Light of Exodus.\n\nI never believed him... until now.\n\nYour scouts have found a crystal that sounds just like it. It has been taken by a terrible demon and is being corrupted at the Beacon of Sha'tar in Shattrath.\n\nWe have to hurry!", progress = "If the Light of Exodus is half as powerful as my grandfather told me, we cannot let it fall into the Legion's hands.", completion = "It's so beautiful...\n\nOh, commander, thank you. A million times thank you!", objectives = "Retrieve the Light of Exodus from Ambassador Hellmaw at Beacon of Sha'tar in Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37128] = { id = 37128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Settling Grievances", description = "Our scouts have found a powerful draenei crystal being corrupted by Ambassador Hellmaw at the Beacon of Sha'tar in Shattrath. The draenei call it the Light of Exodus.\n\nCommander, I'd like to accompany you on this mission. Hellmaw slew my brother in Outland... this is personal.", progress = "We cannot allow the Legion to gain any advantage.", completion = "It is done. The Legion have suffered a mighty blow.", objectives = "Retrieve the Light of Exodus from Ambassador Hellmaw at Beacon of Sha'tar in Shattrath City in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37129] = { id = 37129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Memories", description = "The botani in the Everbloom Wilds are doin' some sorta foul magic to create these plant... well... zombies, basically.\n\nI've seen what happens with armies o' mindless slaves. The Lich King...\n\n<Delvar's eyes close.>\n\nNo matter. We cannae let this escalate any further. I heard o' a particularly nasty one they've just made... let's kill it and see what makes it tick.", progress = "No zombies, plant o' otherwise, are goin' ta walk this world if ol' Delvar has anythin' to say about it.", completion = "I'll be takin' a close look at this... thing. We can't have a repeat o' Northrend.", objectives = "Retrieve Infested Orc Remains from Acanthus at Everbloom Wilds in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37130] = { id = 37130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37131] = { id = 37131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Lady's Concern", description = "The botani in the Everbloom Wilds kill anything foolish enough to wander too close to their blooms and are raising their corpses as mindless soldiers.\n\nThis is all too reminiscent of the Scourge... and the Dark Lady has taken notice. She has a special mission for us, commander.\n\nThere is a particularly large infested creature that was recently raised. We are to destroy it and retrieve its remains.", progress = "I assure you, commander, the Dark Lady has the Horde's best interests at heart. We must stop these botani immediately.", completion = "Thank you, commander. The Dark Lady will appreciate this greatly.", objectives = "Retrieve Infested Orc Remains from Acanthus at Everbloom Wilds in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37132] = { id = 37132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37133] = { id = 37133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37134] = { id = 37134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37135] = { id = 37135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37136] = { id = 37136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunspring POI Tracking Quest" }
quests[37137] = { id = 37137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying Hard or Hardly Scrying", description = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs.\n\nThey have begun to master their craft... they call to the shadows beyond this realm...\n\nI desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", progress = "Taking out our enemies and gaining great power in one motion... my people have a saying for this: Killing two orcs with one stone.", completion = "Yes... yes... this will do nicely. We can use this to do great things.\n\nThank you, commander.", objectives = "Retrieve Urna's Fathomstaff from Urna Darkfathom at Shadowmoon Enclave in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37140] = { id = 37140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leorajh's Prayer Beads", description = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements.\n\nOne day bird-men attacked and took prayer beads. Took them to Skettis.\n\nMaster, you help Leorajh get prayer beads back?", progress = "Elements don't speak to Leorajh like they used to.", completion = "Thank you, master! Elements speak to Leorajh again.", objectives = "Retrieve Leorajh's Prayer Beads from Kirox the Wind Dancer in Skettis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37141] = { id = 37141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talonpriest Ishaal", objectives = "My purpose as a Talonpriest has been fulfilled, though Iskar and Zellek must think me a fool for altering the sacred rites.\n\nI care not for their approval, and I am done hiding in the shadows.\n\nLet me fight for you. I should like to improve this world before I fade away from it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37142] = { id = 37142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Ancestry", description = "Lunk no like fight, want to learn. You help Lunk learn?\n\nFind Lunk ancestors. Lunk have many question. Where Lunk come from? Why LunkLunk?\n\nLunk stay here. Small ogres mean, big ogres meaner.", progress = "How can LunkLunk if Lunk not know what Lunk is?", completion = "Lunk know you kill many ogre for this, and Lunk very upset about this, but Lunk also still grateful.\n\nWait, dis not Lunk family club...", objectives = "Collect an Ogre Family Tree from the Bloodmaul Slag Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37144] = { id = 37144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon Guard Kurekk", objectives = "You have done much for us. What can I offer, but my blade?\n\nTalon King, let me fight for you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37145] = { id = 37145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Budd's Gambit", description = "Listen, I don't know how I got here, but I have it on good authority that there is an entire island made of shiny things and it's just off of the coast a ways.\n\nAll we have to do is hop in the water and swim out there, then we can load up our pockets and swim back! I'm just going to rest up and do some stretching before heading out.\n\nDon't try and stop me!", progress = "What?", completion = "Oh... this is... well that's very shiny isn't it? I think... I'll just sit here for a while.\n\n<Budd smiles contentedly.>", objectives = "Collect a Very Shiny Thing from the Iron Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37146] = { id = 37146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Fetch", description = "Now THIS is a savage land worthy of my level of heroism!\n\nOh, hello, I did not see you standing there, staring at me. Perhaps you have noticed that every piece of my armor is an ancient relic, forgotten by time.\n\nAs you have properly surmised, an adventurer of my stature does not have time to complete the menial requests I am given daily. I must remain here, yelling aloud to the trade district so that others may witness my heroicness and be inspired.\n\nToday I require a Nightmare Bell, do find one.", progress = "What do you want?", completion = "I see you have completed this menial task admirably, almost as if you were intended to experience such a thing. Ah fate, what do you have in store for me next?", objectives = "Collect a Nightmare Bell from Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37147] = { id = 37147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sky Dancers", description = "Greetings, {name}, and I thank you for your hospitality.\n\nThe Shado-pan have sent several warriors to aid against the Iron Horde, however we can. We are few, though, and they are many.\n\nThe arakkoa in the south are both beautiful and deadly. They appear lighter than air, their attacks a deadly dance that flits from opponent to opponent.\n\nThe winds are on their side, as the four winds lighten the steps of my own allies. Bring me a sample of their winds, if you are able. It will surely aid us.", progress = "Did you find the fifth wind?", completion = "I will take this to the Shado-pan right away. Fortune be with you, we will have need of your help again when the winds run quiet.", objectives = "Collect a Bottled Windstorm from Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37148] = { id = 37148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oralius' Adventure", description = "Me n' Winky, off on adventures again! This is the life, I tell ye. No burning air to breathe, an' plenty of ogres to kill!\n\n<Oralius rubs his belly.>\n\nWe did leave a bit of a mess back there in the Blackrock Spire, though. A whole mess of these iron-plated orcs and some proto-dragons marched right on up from the south and took it over.\n\nOl' Winky, he couldn't take the guilt. Went on back by himself he did, to stop them!\n\nOr... to JOIN them! Winky, ye two-timing son of an orc. Ye've got to stop him!", progress = "Did ye stop him?", completion = "Good thinkin'. Winky always loved these flameflies. If we gather enough of them, maybe we can convince hiim to come back!\n\nMaybe, er, you should hold onto this for a while, eh?", objectives = "Collect a Spire Flamefly in Upper Blackrock Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37149] = { id = 37149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void-Gate", description = "My 'master' is an idiot, but you look like you've got some smarts in that oddly-shaped head.\n\nListen up, the Twisting Nether is a chaotic abyss, and things work differently there. I've felt some disturbances, and they don't bode well for any of us.\n\nYes, there are things happening here, in Draenor, that are causing ripples in the nether. No, don't try to wrap your head around how that works, you'll only hurt yourself.\n\nIt's simple: bring me a Void-Gate Key, and maybe I can stop the bad things.", progress = "You do know that any time you waste talking to me brings us closer to doom, right?", completion = "Perfect, here's a prize for your efforts.\n\nI've got to head out and save everyone now. Again.", objectives = "Find a Void-Gate Key in the Shadowmoon Burial Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37150] = { id = 37150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Birds", description = "Hi! Have you ever held a peachick hatchling?\n\n<Without warning, Mylune grabs both of your hands and then stuffs a tiny chirping bird in them.>\n\nIsn't it so small and light and downy? Like you're holding a beaky peepy lil' CLOUD! It's so adorable you can't help but hug it and cuddle it and stuff regurgitated food in its teeny-tiny mouth.\n\n{name}, the plantfolk in the Everbloom are turning peachicks into monsters before they can grow into beautiful swans. Or whatever they grow into. Please help them!", progress = "Have you rescued a peachick? We're all they have, and those awful plant creatures are doing terrible things to them!\n\n<Mylune's voice suddenly drops two octaves and sends a chill up your spine.>\n\nTerrible. Things.", completion = "<Mylune gently lifts the tiny little bird to her face, nuzzling it. It crawls onto her shoulder and disappears into her nest of green hair. A moment later, a beautiful fan of brightly-colored tailfeathers emerges from the top of her head.>\n\n<Mylune's bright blue eyes grow moist with tears and her mouth goes slack with adoration. You've made the dryad VERY happy.>", objectives = "Find a Tiny Peachick Hatchling in The Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37151] = { id = 37151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cold Steel", description = "Do you know what I want? What everyone who came through that portal wants. Every soldier running from a world that didn't understand us, didn't need us. I want that world to love us as much as we love it.\n\nBut we don't really belong there, not anymore. War is part of us, and we can't go back. To everyone back there, we're expendable.\n\nThe only thing that makes me feel better now is the feel of a cold iron cannon in my hands, pointed at the enemy.\n\n<Keeshan stares into his mug of ale.>", progress = "Leave me alone.", completion = "Yeah, this will do nicely. I'm going to run out of ammo, but at least I've got something to live for, for a while.\n\nHere, kid, you're gonna need this more than I am.", objectives = "Find an Iron Autocannon in Grimrail Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37152] = { id = 37152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cro's Revenge", description = "HA! The fruit vendor was so cunning, but I, Cro Threadstrong, am even MORE cunning. I have come back into the past to defeat the ogre army before that fruit vendor can turn them against me!\n\nBring me the head of a big, strong ogre from the old slag mines, and I will have crushed the fruit vendor before a single apple has even grown!\n\nCAN YOU HEAR ME, FRUIT VENDOR? I WILL HAVE MY VICTORY!", progress = "THE FRUIT VENDOR STANDS NO CHANCE!", completion = "Revenge has the sweetest taste. Like an apple.\n\nTake this, friend. May all of your fruit be CRUSHED INTO PULP LIKE YOUR ENEMIES.", objectives = "Collect a Giant Ogre Head from the Bloodmaul Slag Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37153] = { id = 37153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time-Lost Vikings", description = "Oi, barely made it out of that place!\n\nWe came through the portal to help, and the next thing you know, we're prisoners in the Bloodmaul Slag Mine. It was brutal! We were shackled for days, and covered in filth.\n\nAnd they took my SHIELD!", progress = "<Olaf sobs.>", completion = "Oi, it's a fair sight dirtier, but that's her! Here, this is for you. You have my thanks.", objectives = "Collect Olaf's Shield from the Bloodmaul Slag Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37154] = { id = 37154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cure For Death", description = "Greetings, and my thanks for the warmth of this inn and your hospitality.\n\nAs you can see, this malady of death continues to plague me. My studies on Azeroth and in Northrend met with little luck, and all of my leads ran dry.\n\nI have come to Draenor in the hope of finding something, anything, to go on. My first pilgrimage will be to Auchindoun, a house where souls are put at ease.\n\nIf you should head there yourself, do let me know if you should happen upon anything of interest.", progress = "Did you find anything?", completion = "This... may help me. I will need to return to Light's Hope shortly, you have my thanks.\n\nI will not need these supplies any longer, they are yours.", objectives = "Collect a Soulweave Vessel from Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37155] = { id = 37155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brass Compass", description = "Greetings, commander. I have come on a mission directly from the captain.\n\nAboard any vessel on Azeroth that's manned by at least one orc, you'll hear sea shanties sung about a device capable of navigating the broad, rough ocean of Draenor. The orcs used it to keep their heading true in the choppiest of storms.\n\nPerhaps it's just an old sea tale, but this one chance to find that kind of prize has the captain willing to part with some fine treasure.", progress = "Did you find the compass?", completion = "This might just be what we were looking for. Here's your booty.", objectives = "Find the Brass Compass at the Iron Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37156] = { id = 37156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soulcutter", description = "Don't look at me! Who do you think you are?\n\nYou and I are on the same side, you know. The necromancers here, we have to kill them. All of them.\n\nDon't you agree?\n\nOf course you do, and you can help me accomplish this goal. Find a Soulsever Blade in that hovel where the necromancers have holed up like rats. It has... special properties... that will aid us against the undead.", progress = "Did you find the blade?", completion = "Excellent, most excellent.\n\nI will wear it down quickly, and it cannot be repaired due to its unique nature. Expect to hear from me again.", objectives = "Collect a Soulsever Blade from Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37157] = { id = 37157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeling A Bit Morose", description = "So many years of waking up as a spirit, reanimated by some unseen force time and again, has left one with certain desires - the comforting, velvet blackness of death being chief amongst them.\n\nOne will, however, settle for the lesser prize of a solution capable of removing the scuff marks that the commander's wonderful compatriots left behind in the dining hall in their woefully short stay in Karazhan, whereupon they barely had enough time to irreparably damage the priceless furniture.", progress = "Was the commander successful?", completion = "One is eternally in your debt for what is, one is certain, an entirely selfless act on the part of the commander.\n\nThough more barrels were likely available, one will staunchly make do with the single barrel provided, comforted in the knowledge that the commander must deal with the great pressing issues of this land, and does not have time to clean up the mud that that so dutifully follows the commander's heroic allies.", objectives = "Collect a barrel of Horribly Acidic Solution from the Iron Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37158] = { id = 37158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gloriously Incandescent", description = "I did not come here to fight, I have seen too many die already. I have killed so many with my own hands.\n\nI have come to seek the light, and redemption.\n\nThe arakkoa of this land worship the sun as I do. But they are a violent, isolationist, and decadent race, who seem to derive a different message than my own people. This troubles me.\n\nBring me one of their Sun Crystals. I wish to see this light.", progress = "Did you find the crystal?", completion = "The sun, I can see it. It is so bright.\n\nI... wish to be alone. Take this, and my thanks.", objectives = "Collect a Sun Crystal in Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37159] = { id = 37159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aviana's Request", description = "The arakkoa are creatures of the sky, and are thus within the domain of the great Aviana.\n\nI have been sent to procure a feather, that we may parley with them through the language of the winds. We will extend an invitation of peace, and a place on the Great Bough.\n\nWould you aid us in this quest? The feather must come from an arakkoan of nobility. You will find them in the place known as Skyreach.", progress = "Did you bring a feather?", completion = "My thanks, {name}. Aviana will be pleased, and we may yet be able to aid you.\n\nAviana has sought fit to bless you with this, use it well.", objectives = "Collect some Pristine Plumage in Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37160] = { id = 37160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaving Time", description = "I, Gamon, have come through the dark portal to cleave many orc skulls. Yet my weapon has not kept pace with my rage, and is nicked and dull.\n\nFind me a new weapon - one that is good for removing Hellscream limbs.", progress = "What?", completion = "I like this blade. It will see me through much removing of limbs. Here, for you, something to remember me by.", objectives = "Find an Iron Limbcleaver in Grimrail Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37161] = { id = 37161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Family Traditions", description = "He ran off with it! Oh what am I going to do, what am I going to DO?\n\nMy son, and my knife, they ran off to Blackrock Spire! Well, the knife didn't run, I suppose. That doesn't matter!\n\nYou've got to get it back! Yes, the knife! You've got to get me back my knife!\n\nGo! Now! Stop talking!", progress = "Where's my knife?", completion = "You found it! It's safe! I was so worried! Take this, take it!", objectives = "Find Pip's Improved Skinner in Blackrock Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37162] = { id = 37162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damsels and Dragons", description = "What ho, squire {name}! Forgive my lips, as they bear gravest news. Dragons have taken up stinking residence within the hallowed halls of Blackrock Spire!\n\nThese great wyrms hold a distressed damsel in their scaly graspers. Her name is Zaela, they say. Such a beautiful name!\n\nAs my squire, it is your Light-given duty to adventure yourself into this spire and procure evidence of these dragons, lest I waste my heroism on a dragonless quest.", progress = "Did you find evidence of dragons?", completion = "This is dire evidence indeed! I shall head there presently, to slay no less than twenty of the great beasts.\n\nFor Doloria!", objectives = "Collect a Shed Proto-Dragon Claw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37163] = { id = 37163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowy Secrets", description = "Though the Lich King has been defeated, we are no closer to unlocking the secrets of the Frozen Throne than we were when jousting pointlessly at the Argent Tournament. Bolvar remains resigned to his fate.\n\nPerhaps there is something here, though, that can aid us. Ner'zhul was not always the Lich King, you know. Once, he was a mere orc dabbling in dark powers beyond his comprehension.\n\nFind whatever you can of his early studies, and we may have our answers.", progress = "Did you find any of Ner'zhul's notes?", completion = "You have my thanks. I will bring this back to the Ebon Hold immediately.\n\nTake this, I... acquired it... from one of the Shadowmoon.", objectives = "Collect a Dark Parchment from the Shadowmoon Burial Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37164] = { id = 37164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Huntresses", description = "I do not wish to come out of the shadows, but I mean you no harm. My purpose here is my own secret to keep, I simply needed a warm place to bed down for the night.\n\nI can see that you are not the type to be easily swayed into leaving. Very well, perhaps you can aid me in my search.\n\nI am looking for someone, it is not important who. All you need to know is that I will reward you for any sign of high elven weaponry that you should come across.", progress = "Did you find anything?", completion = "This is... it can't be.\n\nI must be off, here is your reward. I do not part with it lightly...", objectives = "Collect a Silver-Lined Arrow from the Shadowmoon Burial Ground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37165] = { id = 37165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarion Concerns", description = "Ey mon!\n\nDe Cenarion Circle sent Zen'kiki out here ta check out dem primals. I woulda been here sooner, but I had a little bit o' trouble gettin' my flight form ta work, mon.\n\nDe plants in dis place... I can hear dem talk. Dey be yellin' all the time. Angry an' violent yellin'.\n\nWould ya bring Zen'kiki back a leaf from dis Everbloom place dey be talkin' about? Maybe I can figure out what dey want.", progress = "Did ya have much luck, mon?", completion = "Dis... is no good. Dey want to consume da whole planet. How did dey get so angry? What happened to dem? I'm gonna bring dis back to da Circle, we probably gonna need your help again soon.\n\nOne of dem fronds be a bit magical, you hold onto it for a bit.", objectives = "Collect a Strangely-Glowing Frond from Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37166] = { id = 37166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanic Evolution", description = "Ah, hello! Do not look so surprised! Did I not also brave the dangers of the Mogu'shan Vaults? I am more sturdy than I look!\n\nI have learned many things of this wonderful place in history already. Did you know that, just like on our world, the titans once came to this place?\n\nAt least, that is what I believe! Surely there are signs of the titans' presence here, even now. Should you find one, I would very much like to see it!", progress = "Have you found any signs of the titans here?", completion = "This is precisely what I was hoping for! I shall begin to study it immediately.\n\nWhile you were away, I collected these pretty flowers for you!", objectives = "Collect an Overgrown Artifact from The Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37167] = { id = 37167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And No Maces!", description = "There are far too many bright-eyed young rogues being sent through this portal and off to war. If I'm going to start up my academy again, some of them have got to survive this little excursion.\n\nWhile I'm here, I figured I might as well use the opportunity to gather some supplies for my grand opening. You can't start a business without plenty of daggers, after all.\n\nGrab me a crate of weaponry from the Grimrail Depot, there should be plenty lying around. I'll have something nice for you.", progress = "Did you find me some weapons?", completion = "Yes, these will do nicely. My thanks, and here is your reward.\n\nTry not to die, I may need you again.", objectives = "Collect a Huge Crate of Weapons in Grimrail Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37168] = { id = 37168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leorajh, the Enlightened", objectives = "<The strangely gentle saberon brings a massive paw to his chest.>\n\nMe Leorajh. Not like others. Was small... weak. Banished from clan. Not Bloodmane anymore...\n\nLeorajh find cave. Find stone of sunlight. Learn much from stone. Want learn more. Want new clan.\n\nYou strong. Have clan?\n\nLeorajh join?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37169] = { id = 37169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apexis Guardian Ziri'ak", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37177] = { id = 37177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Talon King", completion = "Thank you for coming.", objectives = "Speak with the Shade of Terokk in Veil Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37179] = { id = 37179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For The Children!", description = "Wait, wait! Don't attack me! I've changed!\n\nReally, I've turned over a new leaf, I promise. I haven't said \"DOOOOOOM!\" in months! All I care about now is saving the poor little orphans of Azeroth, whose parents have been taken by this tragic war.\n\nThat's why I'm here! Why, with just a single Miniature Iron Star, I could provide clean water and power for all of the orphans of Azeroth! And no one could stop me!\n\nSo, what do you think, sweetcheeks? Want to help ol' Milhouse save the orphans?", progress = "Did you find the Iron Star?", completion = "You know, you're quite handy, and awfully powerful. Why don't I just follow you for a while?\n\nLook out Draenor, DOOOOOOOOM is coming!", objectives = "Collect a Miniature Iron Star from Upper Blackrock Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37180] = { id = 37180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ogre Without His Sword...", description = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\"\n\nI want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse.\n\nIt would mean a great deal to me. An ogre without his sword isn't an ogre at all.", progress = "I want my sword more than I can tell you, commander.", completion = "Yes... this is it.\n\nCommander, I will cleave your foes like never before now that I have my sword.", objectives = "Retrieve Tormmok's Favorite Sword from Vizier Dar'gud at Broken Precipice in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37181] = { id = 37181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leorajh's Prayer Beads", description = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements.\n\nOne day bird-men attacked and took prayer beads. Took them to Skettis.\n\nMaster, you help Leorajh get prayer beads back?", progress = "Elements don't speak to Leorajh like they used to.", completion = "Thank you, master! Elements speak to Leorajh again.", objectives = "Retrieve Leorajh's Prayer Beads from Kirox the Wind Dancer in Skettis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37182] = { id = 37182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying Hard or Hardly Scrying", description = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs.\n\nThey have begun to master their craft... they call to the shadows beyond this realm...\n\nI desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", progress = "Taking out our enemies and gaining great power in one motion... my people have a saying for this: Killing two orcs with one stone.", completion = "Yes... yes... this will do nicely. We can use this to do great things.\n\nThank you, commander.", objectives = "Retrieve Urna's Fathomstaff from Urna Darkfathom at Shadowmoon Enclave in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37183] = { id = 37183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Critical Path", description = "The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast.\n\nTalador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.", completion = "I won't waste any of your time, sir. Let us discuss strategy.", objectives = "Speak to Dungar Longdrink to secure a flight to Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37184] = { id = 37184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Fight to Nagrand", description = "Commander, good to see you. With the fall of the rangari base at Telaar, Vindicator Yrel, recommended that we establish a new foothold in Nagrand.\n\nI've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that the outpost is nearly complete. He asked me to let you know they are ready for you.\n\nA gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, <sir/ma'am>.", completion = "They came at us... from... nowhere.\n\n<The lieutenant nearly passes out.>", objectives = "Speak with Lieutenant Balfor at the caravan in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37185] = { id = 37185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Summons" }
quests[37186] = { id = 37186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of War" }
quests[37187] = { id = 37187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Portal" }
quests[37188] = { id = 37188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flash of Bronze..." }
