quests[37190] = { id = 37190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde Invasion" }
quests[37191] = { id = 37191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanketsu, The Burning Blade", description = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.\n\nPerhaps someone at your garrison would be interested in seeing this weapon.", completion = "<Lieutenant Thorn handles the weapon, her keen eyes taking note of every line, edge, and scratch. After several moments, she speaks.>\n\nMagnificent.\n\nThis blade was honed by a master craftsman, and imbued with ancient magic.\n\nJust imagine if such a powerful weapon were placed in the hands of a skilled warrior...", objectives = "Bring Sanketsu, the Burning Blade, to Lieutenant Thorn at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37192] = { id = 37192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanketsu, The Burning Blade", description = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.\n\nPerhaps someone at your garrison would be interested in seeing this weapon.", completion = "<Warmaster Zog lifts the blade into the air, admiring its balance and heft.>\n\nNever have I seen a weapon such as this. It was clearly made by a master, imbued with ancient magic, and tested in many a battle.\n\nCommander, I will leave the choice to you, but it would be an honor to see this blade placed in service of this garrison.", objectives = "Bring Sanketsu, the Burning Blade, to Warmaster Zog at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37193] = { id = 37193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The King's Command" }
