quests[37199] = { id = 37199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Visitor: Sappy" }
quests[37201] = { id = 37201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cymre Brightblade", description = "I found some interesting artifacts on a recent dig, and I'd love to put them through their paces to see how they would have performed in their native cultures.  Don't suppose you have anything small and furry that can put up a fight?", progress = "Did you want to pet battle or just talk...", completion = "Thanks for helping me test out these artifacts.", objectives = "Defeat Cymre Brightblade in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
